import { fileURLToPath } from "node:url";
import { CATEGORIES, SYMBOLS, WEIGHTS } from "../src/data.js";

export const NAMES_PATH = fileURLToPath(new URL("../src/names.ts", import.meta.url)).replace(/\\/g, "/");
export const NAMES_REL = "src/names.ts";

function union(name: string, values: readonly string[]): string {
  return `export type ${name} =\n${values.map((v) => `  | ${JSON.stringify(v)}`).join("\n")};\n`;
}

export function namesSource(): string {
  return [
    "// Generated by scripts/codegen.ts from src/data.ts. Do not edit.",
    "",
    union("SymbolName", SYMBOLS.map((s) => s.name)),
    union("SymbolCollection", CATEGORIES.map((c) => c.id)),
    union("SymbolWeight", WEIGHTS.map((w) => w.id)),
  ].join("\n");
}

export async function readNames(): Promise<string | null> {
  const file = Bun.file(NAMES_PATH);
  return (await file.exists()) ? await file.text() : null;
}

export async function writeNames(): Promise<boolean> {
  const content = namesSource();
  if ((await readNames()) === content) return false;
  await Bun.write(NAMES_PATH, content);
  return true;
}

if (import.meta.main) {
  const content = namesSource();
  const current = await readNames();
  const tally = `${SYMBOLS.length} noms, ${CATEGORIES.length} collections, ${WEIGHTS.length} graisses`;

  if (process.argv.includes("--check")) {
    if (current !== content) {
      console.error(`${NAMES_REL} est périmé (${current === null ? "fichier absent" : "contenu différent"}). Lancez : bun run codegen`);
      process.exit(1);
    }
    console.log(`${NAMES_REL} est à jour (${tally}).`);
  } else if (current === content) {
    console.log(`${NAMES_REL} inchangé.`);
  } else {
    await Bun.write(NAMES_PATH, content);
    console.log(`${NAMES_REL} écrit (${tally}).`);
  }
}
